"""Read the per-node configuration artifacts generated by ``netlab create``."""

from __future__ import annotations

import os
import re
from pathlib import Path

MAX_FILE_BYTES = 512 * 1024
_SAFE_NODE_NAME_RE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9_.-]{0,127}$")


def is_safe_node_name(node: str) -> bool:
    """Return whether ``node`` is a bounded, single filesystem segment."""
    return _SAFE_NODE_NAME_RE.fullmatch(node) is not None and node not in {".", ".."}


def read_node_files(topology_path: str | Path, node: str) -> list[dict[str, str]]:
    """Return textual files below ``node_files/<node>`` in stable path order."""
    if not is_safe_node_name(node):
        return []
    node_files = os.path.realpath(os.path.join(os.path.dirname(os.path.realpath(topology_path)), "node_files"))
    root_name = os.path.realpath(os.path.join(node_files, node))
    if not root_name.startswith(node_files + os.sep) or not os.path.isdir(root_name):
        return []
    root = Path(root_name)

    files: list[dict[str, str]] = []
    for path in sorted(root.rglob("*")):
        try:
            candidate_name = os.path.realpath(path)
            if not candidate_name.startswith(root_name + os.sep) or not os.path.isfile(candidate_name):
                continue
            candidate = Path(candidate_name)
            if candidate.stat().st_size > MAX_FILE_BYTES:
                continue
            raw = candidate.read_bytes()
            if b"\0" in raw:
                continue
            content = raw.decode("utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        files.append({"path": candidate.relative_to(root).as_posix(), "content": content})
    return files
